#pragma once

#include "CoreMinimal.h"
#include "GameFramework/GameModeBase.h"
#include "ArenaGameMode.generated.h"

class UArenaHud;
class UArenaPalette;
class UArenaScoreTracker;
struct FArenaStats;

UCLASS()
class PIXELARENA_API AArenaGameMode : public AGameModeBase
{
	GENERATED_BODY()

public:
	virtual void BeginPlay() override;
	virtual void EndPlay(const EEndPlayReason::Type Reason) override;

	void OnGoalScored(int32 TeamIndex);

private:
	UPROPERTY()
	TObjectPtr<UArenaHud> Hud;

	UPROPERTY()
	TObjectPtr<UArenaPalette> Palette;

	// UPROPERTY keeps this referenced by the garbage collector; without it the
	// object was collected mid-session and OnGoalScored crashed on the dangling pointer.
	UPROPERTY()
	TObjectPtr<UArenaScoreTracker> ScoreTracker = nullptr;

	// Plain C++ data owned by this class, freed in EndPlay.
	FArenaStats* Stats = nullptr;
};


--- result.json ---
{
  "crash_cause": "UArenaScoreTracker* ScoreTracker in AArenaGameMode had no UPROPERTY() macro, so the garbage collector did not see the reference and destroyed the NewObject'd tracker after a collection (log: 'LogGarbage: Collecting garbage: 412 objects purged'). The next goal dereferenced the dangling pointer: EXCEPTION_ACCESS_VIOLATION in UArenaScoreTracker::AddPoints() called from AArenaGameMode::OnGoalScored(). Fixed by marking ScoreTracker as UPROPERTY() (TObjectPtr) in ArenaGameMode.h.",
  "no_colors_cause": "The palette asset /Game/Data/Palettes/DA_Primary is loaded by string path via LoadObject, which the Unreal cooker cannot detect as a reference, and /Game/Data/Palettes was not in DirectoriesToAlwaysCook in Config/DefaultGame.ini (bCookAll=False), so the asset was never cooked into the packaged build. Log: \"Couldn't find file for package /Game/Data/Palettes/DA_Primary\" and 'Palette is null, using fallback gray'. It works in the editor because editor asset registry finds uncooked assets. Fixed by adding +DirectoriesToAlwaysCook=(Path=\"/Game/Data/Palettes\") to Config/DefaultGame.ini."
}
